import {record,results} from './progress.js?v=733a7b1';
/* 300 deterministic beginner exercises: 9-max only; teaching examples, not solver evaluations. */
const ranks='AKQJT98765432';
const hands=['AA','KK','QQ','JJ','TT','99','88','77','66','AKs','AQs','AJs','ATs','KQs','KJs','QJs','JTs','AKo','AQo','AJo','KQo','55','44','33','22','A9s','KTs','QTs','T9s','98s'];
const positions=['UTG','UTG+1','UTG+2','LJ','HJ','CO','BTN','SB','BB'];
const scenarios=[
 {key:'early',name:'POSIÇÃO INICIAL',positions:['UTG','UTG+1','UTG+2'],hands:['AA','KK','QQ','JJ','TT','AKs','AQs','AKo']},
 {key:'middle',name:'POSIÇÃO INTERMEDIÁRIA',positions:['LJ','HJ'],hands:['AA','KK','QQ','JJ','TT','99','88','AKs','AQs','AJs','KQs','AKo','AQo']},
 {key:'late',name:'POSIÇÃO FINAL',positions:['CO','BTN'],hands:['AA','KK','QQ','JJ','TT','99','88','77','66','AKs','AQs','AJs','ATs','KQs','KJs','QJs','JTs','AKo','AQo','AJo','KQo']},
 {key:'blinds',name:'BLINDS',positions:['SB','BB'],hands:['AA','KK','QQ','JJ','TT','AKs','AQs','AKo']}
];
// Enumerate distinct hand/position contexts, rather than cycling modulo 300.
const uniqueContexts=[];
const allHands=[];for(let i=0;i<ranks.length;i++){for(let j=0;j<ranks.length;j++){allHands.push(i===j?ranks[i]+ranks[j]:i<j?ranks[i]+ranks[j]+'s':ranks[j]+ranks[i]+'o')}}
for(const group of scenarios){for(const position of group.positions){for(const hand of allHands){if(position==='BB')continue;uniqueContexts.push({position,hand,group})}}}
export const rangeActivities=uniqueContexts.sort((a,b)=>{const order=['UTG','UTG+1','UTG+2','LJ','HJ','CO','BTN','SB'];return ((allHands.indexOf(a.hand)*7+order.indexOf(a.position)*37)%1379)-((allHands.indexOf(b.hand)*7+order.indexOf(b.position)*37)%1379)}).slice(0,300).map(({position,hand,group},i)=>{const correct=group.hands.includes(hand)?'ABRIR':'FOLD';return {id:i+1,position,hand,group:group.name,correct,question:'Todos desistiram antes de você. Com '+hand+' em '+position+', qual opção corresponde ao exemplo básico de abertura?',explanation:correct==='ABRIR'?'Neste exemplo didático de 9 jogadores, '+hand+' faz parte do grupo de mãos apresentado para '+group.name.toLowerCase()+'.':'Neste exemplo introdutório, '+hand+' fica fora do grupo selecionado para '+group.name.toLowerCase()+'. Isso não significa que a mão nunca possa ser jogada.'}});
if(rangeActivities.length!==300||new Set(rangeActivities.map(a=>a.position+'|'+a.hand)).size!==300)throw new Error('As 300 atividades precisam ter contextos únicos.');
export function rangesActivitiesPage(){return `<section class="ranges-activity-page"><a href="#practice" class="back">← VOLTAR</a><h2>NOÇÃO DE RANGES · 300 ATIVIDADES</h2><p>Exercícios interativos de introdução para mesas de 9 jogadores. São exemplos didáticos, não avaliações de estratégia ótima. As respostas mudam conforme a posição.</p><div class="ranges-activity-progress" aria-live="polite"></div><article class="ranges-activity-card"><div class="ranges-activity-context"></div><h3 class="ranges-activity-question"></h3><div class="ranges-activity-choices"></div><div class="ranges-activity-result" aria-live="polite"></div><button type="button" class="ranges-activity-next" disabled>PRÓXIMA ATIVIDADE</button></article></section>`}
export function setupRangesActivities(root){const page=root.querySelector('.ranges-activity-page');if(!page)return;let index=0,correctCount=0,answered=false;const sessionId=crypto.randomUUID(),XP_PER_CORRECT=20;const completed=new Set(results().filter(row=>row.module==='group-ranges').map(row=>row.question));const progress=page.querySelector('.ranges-activity-progress'),context=page.querySelector('.ranges-activity-context'),question=page.querySelector('.ranges-activity-question'),choices=page.querySelector('.ranges-activity-choices'),result=page.querySelector('.ranges-activity-result'),next=page.querySelector('.ranges-activity-next');function draw(){const a=rangeActivities[index];answered=false;progress.textContent='ATIVIDADE '+(index+1)+' / 300 · ACERTOS '+correctCount;context.textContent='9 JOGADORES · '+a.position+' · '+a.hand+' · '+a.group;question.textContent=a.question;result.textContent='';choices.replaceChildren();next.disabled=true;next.textContent=index===299?'CONCLUIR':'PRÓXIMA ATIVIDADE';for(const option of (a.correct==='OBSERVAR'?['OBSERVAR','ABRIR','FOLD']:['ABRIR','FOLD','ALL IN'])){const b=document.createElement('button');b.type='button';b.textContent=option;b.addEventListener('click',()=>{if(answered)return;answered=true;const ok=option===a.correct;if(ok)correctCount++;const questionId='range-'+a.id;const earned=ok&&!completed.has(questionId)?XP_PER_CORRECT:0;record({module:'group-ranges',theme:'ranges',session:sessionId,question:questionId,correct:ok,xp:earned,difficulty:'standard'});completed.add(questionId);result.textContent=(ok?'CORRETO! '+(earned?'+'+earned+' XP. ':'XP já contabilizado. '):'REVISE: '+a.correct+'. ')+a.explanation;choices.querySelectorAll('button').forEach(btn=>{btn.disabled=true;btn.setAttribute('aria-pressed',String(btn===b))});next.disabled=false;progress.textContent='ATIVIDADE '+(index+1)+' / 300 · ACERTOS '+correctCount});choices.append(b)}}next.addEventListener('click',()=>{if(!answered)return;if(index===299){progress.textContent='CONCLUÍDO · '+correctCount+' / 300 ACERTOS';next.disabled=true;return}index++;draw()});draw()}
